from dataclasses import dataclass, field


@dataclass
class SearchRecConfig:
    db_path: str = "./rec.db"

    # ML thresholds
    min_sessions_to_retrain: int = 10
    min_coclick: int = 2
    top_n: int = 10

    # API limits
    recommend_limit_default: int = 10
    recommend_limit_max: int = 50

    # Frontend — must match the prefix= passed to app.include_router()
    frontend_prefix: str = ""
    serve_frontend: bool = True

    # CORS — None means the host app owns CORS (most common when embedded)
    cors_origins: list[str] | None = None
